// Temporary passwords (AD-2, AD-3): generated by the service, shown once to the DM, valid until the
// player chooses their own (story 2.3). Never stored or logged here.

import { randomInt } from 'node:crypto';

// No look-alike characters (0/O, 1/l/I) so the DM can read it out loud or type it from a phone.
const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789';
export const TEMP_PASSWORD_LENGTH = 16;

export function generateTemporaryPassword(length: number = TEMP_PASSWORD_LENGTH): string {
  let out = '';
  for (let i = 0; i < length; i++) out += ALPHABET[randomInt(ALPHABET.length)];
  return out;
}
